      "description": "Catherine whispers she can burn the book and mentions finding Juliana's corpse at the end of a rope."
    },
    {
      "start_block": "B046",
      "end_block": "B048",
      "kind": "reveal",
      "description": "Catherine mocks Juliana's 'scarred soldier' husband, questioning what a penniless veteran can do."
    },
    {
      "start_block": "B071",
      "end_block": "B073",
      "kind": "emotional",
      "description": "Juliana vows they will not take Alexander from her as the massive iron portcullis crashes down."
    }
  ]
